/**
 * @brief 预设的摇杆方向选择，若未覆盖则使用 0 度。
 *        用户可在项目配置中覆写该宏以适配硬件放置方向。
 */
#ifndef ADC_JOYSTICK_DEFAULT_ORIENTATION
