 */
uint8_t adc_joystick_test_run(uint32_t sample_count, uint32_t delay_ms);

/**
 * @brief     持续采样摇杆，并通过 UART 发送小键盘方向码。
 * @param[in] sample_count 处理的采样次数，0 表示默认/持续运行。
