 *            - 3 UART 发送失败
 */
uint8_t adc_joystick_send_udlr_uart(uint32_t sample_count, uint32_t delay_ms, UART_HandleTypeDef *huart);


/**
 * @brief 读取摇杆按键状态。
 * @return 按下返回 1，否则返回 0
 */
uint8_t adc_joystick_test_read_key(void);
