#include "crc.h"

uint16_t __weak crc16(uint16_t poly, uint16_t seed, const uint8_t *src, size_t len)
{
    uint16_t crc = seed;
    size_t i, j;

    for (i = 0; i &lt; len; i++) {
        crc ^= (uint16_t)(src[i] &lt;&lt; 8U);

        for (j = 0; j &lt; 8; j++) {
            if (crc &amp; 0x8000UL) {
                crc = (crc &lt;&lt; 1U) ^ poly;
            } else {
                crc = crc &lt;&lt; 1U;
            }
        }
    }

    return crc;
}

uint16_t __weak crc16_reflect(uint16_t poly, uint16_t seed, const uint8_t *src, size_t len)
{
    uint16_t crc = seed;
    size_t i, j;

    for (i = 0; i &lt; len; i++) {
        crc ^= (uint16_t)src[i];

        for (j = 0; j &lt; 8; j++) {
            if (crc &amp; 0x0001UL) {
                crc = (crc &gt;&gt; 1U) ^ poly;
            } else {
                crc = crc &gt;&gt; 1U;
            }
        }
    }

    return crc;
}

uint16_t __weak crc16_ccitt(uint16_t seed, const uint8_t *src, size_t len)
{
    for (; len &gt; 0; len--) {
        uint8_t e, f;

        e = seed ^ *src;
        ++src;
        f = e ^ (e &lt;&lt; 4);
        seed = (seed &gt;&gt; 8) ^ ((uint16_t)f &lt;&lt; 8) ^ ((uint16_t)f &lt;&lt; 3) ^ ((uint16_t)f &gt;&gt; 4);
    }

    return seed;
}

uint16_t __weak crc16_itu_t(uint16_t seed, const uint8_t *src, size_t len)
{
    for (; len &gt; 0; len--) {
        seed = (seed &gt;&gt; 8U) | (seed &lt;&lt; 8U);
        seed ^= *src;
        ++src;
        seed ^= (seed &amp; 0xffU) &gt;&gt; 4U;
        seed ^= seed &lt;&lt; 12U;
        seed ^= (seed &amp; 0xffU) &lt;&lt; 5U;
    }

    return seed;
}
