uint32_t crc24q_rtcm3(const uint8_t *data, size_t len)
{
    uint32_t crc = 0;

    for (uint32_t i = 0; i &lt; len; ++i) {
        crc = ((crc &lt;&lt; 8) &amp; 0xFFFFFF) ^ crc24q[data[i] ^ (crc &gt;&gt; 16)];
    }

    return crc;
}
