/* 阻塞方式发送字符串到调试串口 */
static void console_send_string(const char *msg)
{
  if (msg == NULL)
  {
    return;
  }
  HAL_UART_Transmit(&amp;huart2, (uint8_t *)msg, strlen(msg), HAL_MAX_DELAY);
}

/* 输出下一条命令的提示符 */
