/**
  * @brief  The application entry point.
  * @retval int
  */
int main(void)
{
  HAL_Init();
  SystemClock_Config();
  MX_GPIO_Init();
  MX_USART2_UART_Init();

  shell_show_banner();
  microrl_init(&amp;s_shell, shell_print);
  microrl_set_execute_callback(&amp;s_shell, shell_execute);
  microrl_set_complete_callback(&amp;s_shell, shell_complete);
  shell_start_rx();

  while (1)
  {
    shell_process_input();
  }
}

