//#define DBG(...) fprintf(stderr, "\033[33m");fprintf(stderr,__VA_ARGS__);fprintf(stderr,"\033[0m");

char * prompt_default = _PROMPT_DEFAULT;

#ifdef _USE_HISTORY

#ifdef _HISTORY_DEBUG
//*****************************************************************************
// print buffer content on screen
static void print_hist (ring_history_t * pThis)
{
    printf ("\n");
    for (int i = 0; i &lt; _RING_HISTORY_LEN; i++) {
        if (i == pThis-&gt;begin)
            printf ("b");
        else 
            printf (" ");
    }
    printf ("\n");
    for (int i = 0; i &lt; _RING_HISTORY_LEN; i++) {
        if (isalpha(pThis-&gt;ring_buf[i]))
            printf ("%c", pThis-&gt;ring_buf[i]);
        else 
            printf ("%d", pThis-&gt;ring_buf[i]);
    }
    printf ("\n");
    for (int i = 0; i &lt; _RING_HISTORY_LEN; i++) {
        if (i == pThis-&gt;end)
            printf ("e");
        else 
            printf (" ");
    }
    printf ("\n");
}
#endif

//*****************************************************************************
// remove older message from ring buffer
static void hist_erase_older (ring_history_t * pThis)
{
    int new_pos = pThis-&gt;begin + pThis-&gt;ring_buf [pThis-&gt;begin] + 1;
    if (new_pos &gt;= _RING_HISTORY_LEN)
        new_pos = new_pos - _RING_HISTORY_LEN;

    pThis-&gt;begin = new_pos;
}

//*****************************************************************************
// check space for new line, remove older while not space
static int hist_is_space_for_new (ring_history_t * pThis, int len)
{
    if (pThis-&gt;ring_buf [pThis-&gt;begin] == 0)
        return true;
    if (pThis-&gt;end &gt;= pThis-&gt;begin) {
        if (_RING_HISTORY_LEN - pThis-&gt;end + pThis-&gt;begin - 1 &gt; len)
            return true;
    }   else {
        if (pThis-&gt;begin - pThis-&gt;end - 1&gt; len)
            return true;
    }
    return false;
}

//*****************************************************************************
// put line to ring buffer
static void hist_save_line (ring_history_t * pThis, char * line, int len)
{
    if (len &gt; _RING_HISTORY_LEN - 2)
        return;
    while (!hist_is_space_for_new (pThis, len)) {
        hist_erase_older (pThis);
    }
    // if it's first line
    if (pThis-&gt;ring_buf [pThis-&gt;begin] == 0) 
        pThis-&gt;ring_buf [pThis-&gt;begin] = len;

    // store line
    if (len &lt; _RING_HISTORY_LEN-pThis-&gt;end-1)
        memcpy (pThis-&gt;ring_buf + pThis-&gt;end + 1, line, len);
    else {
        int part_len = _RING_HISTORY_LEN-pThis-&gt;end-1;
        memcpy (pThis-&gt;ring_buf + pThis-&gt;end + 1, line, part_len);
        memcpy (pThis-&gt;ring_buf, line + part_len, len - part_len);
    }
    pThis-&gt;ring_buf [pThis-&gt;end] = len;
    pThis-&gt;end = pThis-&gt;end + len + 1;
    if (pThis-&gt;end &gt;= _RING_HISTORY_LEN)
        pThis-&gt;end -= _RING_HISTORY_LEN;
    pThis-&gt;ring_buf [pThis-&gt;end] = 0;
    pThis-&gt;cur = 0;
#ifdef _HISTORY_DEBUG
    print_hist (pThis);
#endif
}

//*****************************************************************************
// copy saved line to 'line' and return size of line
static int hist_restore_line (ring_history_t * pThis, char * line, int dir)
{
    int cnt = 0;
    // count history record 
    int header = pThis-&gt;begin;
    while (pThis-&gt;ring_buf [header] != 0) {
        header += pThis-&gt;ring_buf [header] + 1;
        if (header &gt;= _RING_HISTORY_LEN)
            header -= _RING_HISTORY_LEN; 
        cnt++;
    }

    if (dir == _HIST_UP) {
        if (cnt &gt;= pThis-&gt;cur) {
            int header = pThis-&gt;begin;
            int j = 0;
            // found record for 'pThis-&gt;cur' index
            while ((pThis-&gt;ring_buf [header] != 0) &amp;&amp; (cnt - j -1 != pThis-&gt;cur)) {
                header += pThis-&gt;ring_buf [header] + 1;
                if (header &gt;= _RING_HISTORY_LEN)
                    header -= _RING_HISTORY_LEN;
                j++;
            }
            if (pThis-&gt;ring_buf[header]) {
                    pThis-&gt;cur++;
                // obtain saved line
                if (pThis-&gt;ring_buf [header] + header &lt; _RING_HISTORY_LEN) {
                    memset (line, 0, _COMMAND_LINE_LEN);
                    memcpy (line, pThis-&gt;ring_buf + header + 1, pThis-&gt;ring_buf[header]);
                } else {
                    int part0 = _RING_HISTORY_LEN - header - 1;
                    memset (line, 0, _COMMAND_LINE_LEN);
                    memcpy (line, pThis-&gt;ring_buf + header + 1, part0);
                    memcpy (line + part0, pThis-&gt;ring_buf, pThis-&gt;ring_buf[header] - part0);
                }
                return pThis-&gt;ring_buf[header];
            }
        }
    } else {
        if (pThis-&gt;cur &gt; 0) {
                pThis-&gt;cur--;
            int header = pThis-&gt;begin;
            int j = 0;

            while ((pThis-&gt;ring_buf [header] != 0) &amp;&amp; (cnt - j != pThis-&gt;cur)) {
                header += pThis-&gt;ring_buf [header] + 1;
                if (header &gt;= _RING_HISTORY_LEN)
                    header -= _RING_HISTORY_LEN;
                j++;
            }
            if (pThis-&gt;ring_buf [header] + header &lt; _RING_HISTORY_LEN) {
                memcpy (line, pThis-&gt;ring_buf + header + 1, pThis-&gt;ring_buf[header]);
            } else {
                int part0 = _RING_HISTORY_LEN - header - 1;
                memcpy (line, pThis-&gt;ring_buf + header + 1, part0);
                memcpy (line + part0, pThis-&gt;ring_buf, pThis-&gt;ring_buf[header] - part0);
            }
            return pThis-&gt;ring_buf[header];
        } else {
            /* empty line */
            return 0;
        }
    }
    return -1;
}
#endif








//*****************************************************************************
// split cmdline to tkn array and return nmb of token
static int split (microrl_t * pThis, int limit, char const ** tkn_arr)
{
    int i = 0;
    int ind = 0;
    while (1) {
        // go to the first whitespace (zerro for us)
        while ((pThis-&gt;cmdline [ind] == '\0') &amp;&amp; (ind &lt; limit)) {
            ind++;
        }
        if (!(ind &lt; limit)) return i;
        tkn_arr[i++] = pThis-&gt;cmdline + ind;
        if (i &gt;= _COMMAND_TOKEN_NMB) {
            return -1;
        }
        // go to the first NOT whitespace (not zerro for us)
        while ((pThis-&gt;cmdline [ind] != '\0') &amp;&amp; (ind &lt; limit)) {
            ind++;
        }
        if (!(ind &lt; limit)) return i;
    }
    return i;
}


