static bool Bootloader_IsApplicationValid(void)
{
  uint32_t appStackPointer = *(__IO uint32_t *)(APP_START_ADDRESS);
  uint32_t appResetHandler = *(__IO uint32_t *)(APP_START_ADDRESS + 4U);

  bool stackPointerInRange = (appStackPointer &gt;= SRAM_START_ADDRESS) &amp;&amp; (appStackPointer &lt;= SRAM_END_ADDRESS);
  bool resetHandlerInRange = (appResetHandler &gt;= APP_START_ADDRESS) &amp;&amp; (appResetHandler &lt;= APP_END_ADDRESS);

  return stackPointerInRange &amp;&amp; resetHandlerInRange;
}

static void Bootloader_JumpToApplication(void)
{
  uint32_t appStackPointer = *(__IO uint32_t *)(APP_START_ADDRESS);
  uint32_t appResetHandler = *(__IO uint32_t *)(APP_START_ADDRESS + 4U);
  AppEntryFunction application = (AppEntryFunction)appResetHandler;

  __disable_irq();
  Bootloader_DeInitPeripherals();
  HAL_RCC_DeInit();
  HAL_DeInit();
  SysTick-&gt;CTRL = 0U;
  SysTick-&gt;LOAD = 0U;
  SysTick-&gt;VAL = 0U;
  __set_MSP(appStackPointer);
  SCB-&gt;VTOR = APP_START_ADDRESS;
  __enable_irq();

  application();
}

static bool Bootloader_IsKeyPressed(void)
{
  return HAL_GPIO_ReadPin(BOOT_KEY_GPIO_PORT, BOOT_KEY_GPIO_PIN) == BOOT_KEY_PRESSED_STATE;
}

static bool Bootloader_ShouldEnterUpgradeMode(void)
{
  uint32_t startTick = HAL_GetTick();

  if (Bootloader_IsKeyPressed())
  {
    printf("[BOOT] Upgrade key pressed at startup.\r\n");
    return true;
  }

  printf("[BOOT] Waiting up to %lu ms for upgrade key...\r\n", (unsigned long)BOOT_KEY_DETECTION_WINDOW_MS);

  while ((HAL_GetTick() - startTick) &lt; BOOT_KEY_DETECTION_WINDOW_MS)
  {
    if (Bootloader_IsKeyPressed())
    {
      printf("[BOOT] Upgrade request detected (elapsed %lu ms).\r\n", (unsigned long)(HAL_GetTick() - startTick));
      return true;
    }
    HAL_Delay(BOOT_KEY_SAMPLE_PERIOD_MS);
  }

  printf("[BOOT] No upgrade request detected.\r\n");
  return false;
}

static void Bootloader_RunUpgradeMode(void)
{
  printf("[BOOT] Entering YMODEM upgrade mode.\r\n");

  while (1)
  {
    ymodem_recv("");
    printf("[BOOT] YMODEM session finished.\r\n");

    if (Bootloader_IsApplicationValid())
    {
      printf("[BOOT] Firmware valid, jumping to application.\r\n");
      Bootloader_JumpToApplication();
    }

    printf("[BOOT] Firmware invalid or upgrade aborted, waiting for another transfer.\r\n");
    HAL_Delay(500U);
  }
}

static void Bootloader_DeInitPeripherals(void)
{
  HAL_UART_DeInit(&amp;huart2);
  HAL_GPIO_DeInit(key_GPIO_Port, key_Pin);
}
