    if (soft_i2c_send_byte(reg))
    {
        soft_i2c_stop();
        return 1;
    }
    for (uint16_t i = 0; i &lt; len; ++i)
    {
        if (soft_i2c_send_byte(buf[i]))
        {
            soft_i2c_stop();
            return 1;
        }
    }
    soft_i2c_stop();

    return 0;
}

