        }
        else                                                                                                  /* check data 0 */
        {
            if (a_check_frame(handle-&gt;decode[2 + i * 2 + 1].diff_us, IR_REMOTE_CHECK_DATA0_LOW) != 0)         /* check data 0 */
            {
                data.address = 0x00;                                                                          /* set address 0x00 */
                data.command = 0x00;                                                                          /* set command 0x00 */
                data.status = IR_REMOTE_STATUS_ADDR_ERR;                                                      /* address error */
                if (handle-&gt;receive_callback != NULL)                                                         /* check the receive callback */
                {
