    for (i = 0; i &lt; 8; i++)                                                                                   /* parse 8 bit */
    {
        if (a_check_frame(handle-&gt;decode[50 + i * 2 + 0].diff_us, IR_REMOTE_CHECK_DATA1_HIGH) != 0)           /* check data high */
        {
            if (handle-&gt;receive_callback != NULL)                                                             /* check the receive callback */
            {
