#define SUPPLY_VOLTAGE_MIN        4.8f                      /**&lt; chip min supply voltage */
#define SUPPLY_VOLTAGE_MAX        5.0f                      /**&lt; chip max supply voltage */
#define MAX_CURRENT               15.0f                     /**&lt; chip max current */
